import { createRequire } from 'node:module'

const require = createRequire(import.meta.url)
const postcss = require('./lib/postcss')

const root = postcss.parse('a {\n  color: red;\n}\nb {\n  color: blue;\n}\n')
const ref = root.first

// Insert a new rule before the first node with before()
ref.before(postcss.rule({ selector: 'c' }))

const out = root.toString()

// The new node should be separated from the reference node by a newline
if (!/c\s*\{\s*\}\s*\n\s*a \{/.test(out)) {
  console.log(
    'WHOBROKEIT_BUG: expected a newline between the node inserted with before() ' +
      'and the reference node, but got ' + JSON.stringify(out)
  )
  process.exitCode = 1
}
